class BackgroundTasks:
    def __init__(self):
        self.tasks = []
    def add_task(self, fn, *args):
        self.tasks.append((fn, args))

def send_email(to):
    print("email ->", to)

def endpoint(bg):
    bg.add_task(send_email, "seller@x.com")
    print("handler done")
    return {"status": "queued"}

bg = BackgroundTasks()
response = endpoint(bg)
print("response sent:", response)
for fn, args in bg.tasks:
    fn(*args)

